import type { ReactNode } from "react";

export type BrandIconProps = Readonly<{ className?: string }>;

export function BrandSvg({
  className,
  viewBox,
  children,
}: BrandIconProps & Readonly<{ viewBox: string; children: ReactNode }>) {
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      viewBox={viewBox}
      className={className}
      fill="currentColor"
    >
      {children}
    </svg>
  );
}

